/// <summary>
/// N.Freidenberger 16.05.2024
/// </summary>
/// <param name = "_valueType">_valueType</param>
/// <returns>boolean></returns>
protected boolean resolve(SysIFilterValueType       _valueType)
{
    boolean  ret = false;

    switch (_valueType.parmTypeIdentifier())
    {
        case extendedTypeNum(WorkerSalesResponsible)  :
            FieldId  rangeField = fieldNum(KCS_KBVRequestTable,AVAWorkerSalesTaker);
            QueryBuildDataSource  qbds = query.dataSourceTable(tableNum(KCS_KBVRequestTable));
            this.addLinkFromTableToFilter(qbds,rangeField);
            ret = true;
            break;
    }

    return ret;
}
